INSERT INTO manufacturer_assets
  (id, category, equipment_id, brand, model, asset_type, source_url, page_ref, image_url, doc_title, verified, notes)
VALUES
  ('racking_detail:rooftech-mini', 'racking_detail', 'rooftech-mini', 'Roof Tech', 'RT-MINI', 'image', 'https://design.roof-tech.us/PDF/Installation-Manuals/Installation-Manual-RT-MINI-II.pdf', 'p.9-20 (Part B Bracket Installation cross-sections, rafter attach ~p.11, deck attach ~p.12/p.20)', '/manufacturer-assets/racking_detail_rooftech-mini.png', 'Roof Tech RT-MINI II Installation Manual (Jun 2025)', TRUE, 'Fetched from official design.roof-tech.us and text-extracted (40 pp). Rail-less direct-attach cross-section: MINI base over shingle, RT-Butyl/EPDM butyl flashing, 5.0x60mm SS wood screws into rafter center (or 5x deck screws). RT-MINI is superseded by RT-MINI II, this is the current manufacturer install doc. Legacy standalone RT-MINI manual (Jan 2021, 33 pp, also verified): https://design.roof-tech.us/PDF/Installation-Manuals/Installation-Manual-RT-MINI.pdf'),
  ('racking_detail:rooftech-mini-s', 'racking_detail', 'rooftech-mini-s', 'Roof Tech', 'RT-MINI-S', 'image', 'https://design.roof-tech.us/PDF/Installation-Manuals/Installation-Manual-RT-MINI-II.pdf', 'p.9-19 (Part B Bracket Installation cross-sections)', '/manufacturer-assets/racking_detail_rooftech-mini-s.png', 'Roof Tech RT-MINI II Installation Manual (Jun 2025)', TRUE, 'No distinct ''RT-MINI-S'' SKU exists in Roof Tech''s catalog (verified against roof-tech.us product/manual index). Treated as an RT-MINI variant, the same verified RT-MINI II manual is the correct source. Standard asphalt-shingle attachment cross-section (rafter/deck, RT-Butyl flashing).'),
  ('racking_detail:rooftech-mini-t', 'racking_detail', 'rooftech-mini-t', 'Roof Tech', 'RT-MINI-T', 'image', 'https://design.roof-tech.us/PDF/Installation-Manuals/Installation-Manual-RT-MINI-II.pdf', 'p.9-19 (base cross-sections), composite-slate/tile-style addendum ~p.28-30', '/manufacturer-assets/racking_detail_rooftech-mini-t.png', 'Roof Tech RT-MINI II Installation Manual (Jun 2025)', TRUE, 'No distinct ''RT-MINI-T'' SKU in Roof Tech''s catalog (verified). If ''T'' denotes tile/composite-slate, the RT-MINI II manual includes a Composite Slate addendum (pilot hole + sealant + deck-screw cross-section) plus the standard base attachment. Same verified manufacturer manual.'),
  ('racking_detail:rooftech-hook', 'racking_detail', 'rooftech-hook', 'Roof Tech', 'RT-HOOK', 'image', 'https://design.roof-tech.us/PDF/Installation-Manuals/Installation-Manual-RT-MINI-II.pdf', 'p.9-19 (base attachment), membrane/roof-type addenda ~p.22-34', '/manufacturer-assets/racking_detail_rooftech-hook.png', 'Roof Tech RT-MINI II Installation Manual (Jun 2025)', FALSE, 'FLAG: No product named ''RT-HOOK'' exists in Roof Tech''s lineup (confirmed via roof-tech.us: RT-MINI II, RT-PLUS, RT-APEX, RT-CONDUIT MOUNT, RT-RAIL). ''Roof hook'' mounts are a competitor category (e.g. Unirac SolarHooks / K2 CrossHook), not Roof Tech. URL resolves and is genuine but is NOT specifically an RT-HOOK doc, hence verified:false. Recommend confirming this equipment_id is real / re-mapping it to the actual hook manufacturer.'),
  ('racking_detail:rooftech-mini-m', 'racking_detail', 'rooftech-mini-m', 'Roof Tech', 'RT-MINI-M', 'image', 'https://design.roof-tech.us/PDF/Installation-Manuals/Installation-Manual-RT-MINI-II.pdf', 'p.22-27 (ADDENDUM: Installation on Metal Roofing) - metal-rib check, RT-Butyl spacer + 5x M5.0x60 SS deck-screw cross-section, sealant slope', '/manufacturer-assets/racking_detail_rooftech-mini-m.png', 'Roof Tech RT-MINI II Installation Manual (Jun 2025) - Metal Roofing Addendum', TRUE, 'No standalone ''RT-MINI-M'' SKU, metal-roof variant is documented as the Metal Roofing addendum inside the verified RT-MINI II manual, showing the metal-roof cross-section (butyl spacer between rib flats, SS wood screws to deck, sealant slope). Dedicated legacy alt doc also verified (18 pp, ''RT-MINI Double/Metal Flashing Option''): https://design.roof-tech.us/PDF/Installation-Manuals/Installation-Manual-RT-MINI-Metal-Flashing-Option.pdf'),
  ('racking_detail:ironridge-xr100', 'racking_detail', 'ironridge-xr100', 'IronRidge', 'XR100 rail', 'image', 'https://files.ironridge.com/pitched-roof-mounting/resources/brochures/IronRidge_Flush_Mount_Installation_Manual.pdf', 'p.10 (composition/FlashFoot2 attachment), p.12 (tile), p.14 (low slope), rail-to-foot bonding p.16+', '/manufacturer-assets/racking_detail_ironridge-xr100.png', 'IronRidge XR Flush Mount Installation Manual (Version 5.x)', TRUE, 'Fetched from official files.ironridge.com (7.3MB, ~32 pp) and text-extracted. Single XR Flush Mount manual covers all XR rails (XR10/XR100/XR1000). Composition attachment method (locate rafter, pilot hole, FlashFoot2, lag bolt into rafter, rail to FlashFoot2 cap, torque 300 in-lbs) is the XR100 asphalt-shingle flush-mount cross-section: ''For composition roof attachments installation instructions refer to page 10.'' FlashFoot2 detail explicitly referenced, full standalone FlashFoot2 manual: https://files.ironridge.com/pitched-roof-mounting/resources/brochures/IronRidge_FlashFoot2_Installation_Manual.pdf'),
  ('racking_detail:ironridge-xr1000', 'racking_detail', 'ironridge-xr1000', 'IronRidge', 'XR1000 rail', 'image', 'https://files.ironridge.com/pitched-roof-mounting/resources/brochures/IronRidge_Flush_Mount_Installation_Manual.pdf', 'p.10 (composition/FlashFoot2 attachment), p.12 (tile), p.14 (low slope), rail-to-foot bonding p.16+', '/manufacturer-assets/racking_detail_ironridge-xr1000.png', 'IronRidge XR Flush Mount Installation Manual (Version 5.x)', TRUE, 'Same verified IronRidge XR Flush Mount manual (files.ironridge.com), it covers the entire XR rail family including the heavy-duty XR1000 (commercial / high wind-and-snow). Attachment cross-section is identical method (rafter, pilot hole, FlashFoot2 lag, rail-to-cap). Rail selection (XR10/XR100/XR1000) is a spacing/load choice, the attachment detail is shared. Data sheet: https://files.ironridge.com/pitched-roof-mounting/resources/brochures/Flush_Mount_Data_Sheet.pdf'),
  ('racking_detail:unirac-solarmount', 'racking_detail', 'unirac-solarmount', 'Unirac', 'SolarMount Classic', 'image', 'https://ressupply.com/documents/unirac/SolarMount_Installation_Manual.pdf', 'TOC-linked: Roof Attachment & L-Feet section (~p.7), L-Foot/rail cross-section, Appendix A FlashKit Pro (~p.39), Appendix F SM Butyl (~p.47-50)', '/manufacturer-assets/racking_detail_unirac-solarmount.png', 'Unirac SM SolarMount Installation Guide (Code-Compliant Installation Manual, 2022)', TRUE, 'Fetched (21.4MB, ~53 pp) and text-extracted, cover ''SM SOLAR MOUNT INSTALLATION GUIDE - UNIRAC Code-Compliant Installation Manual (c) 2022''. TOC includes ''ROOF ATTACHMENT & L-FEET'', ''ATTACH RAIL TO L-FEET'', and flashing appendices (FlashKit Pro, FlashLoc Comp/Duo, SM Butyl) - the L-foot/lag-into-rafter + flashing cross-section. This ressupply mirror resolves reliably, Unirac''s own product page (unirac.com/products/pitched-roof/solarmount/) links the current guide but individual PDF links are gated behind their bsk-pdf-manager. LA County copy also verified: https://pw.lacounty.gov/bsd/lib/fp/Small%20Residential%20Rooftop%20Solar%20Energy%20Systems/LA%20County%20Recognized%20UL%202703%20Racking%20Systems/Unirac%20SM%20SolarMount%20Installation%20Guide.pdf'),
  ('racking_detail:unirac-sme', 'racking_detail', 'unirac-sme', 'Unirac', 'SolarMount Evolution (SME) / Pro Series', 'image', 'https://ressupply.com/documents/unirac/SolarMount_Pro_Series_Installation_Manual.pdf', 'Section D - Roof Attachment & L-Feet, Appendix A System Certification, Appendix B FlashKit Pro Installation (~p.31 doc)', '/manufacturer-assets/racking_detail_unirac-sme.png', 'Unirac SM SolarMount Pro Series Installation Guide (PUB2020JAN07)', TRUE, 'Fetched (9.5MB, ~31 pp, made in Autodesk Inventor) and text-extracted, cover ''SM SOLAR MOUNT ... PUB2020JAN07'', TOC section ''D - ROOF ATTACHMENT & L-FEET'', ''E - SPLICE & THERMAL BREAK'', ''F - ATTACH RAIL TO L-FEET'', ''APPENDIX B: FLASHKIT PRO INSTALLATION''. SolarMount Evolution (SME) is Unirac''s Pro Series line, this is the matching pre-assembled Pro Series install guide with the L-foot/FlashKit Pro attachment cross-section. Reliable ressupply mirror (Unirac''s own bsk-pdf-manager links are gated).'),
  ('racking_detail:snapnrack-100', 'racking_detail', 'snapnrack-100', 'SnapNrack', 'Series 100', 'image', 'https://gridalternatives.org/sites/default/files/SnapNrack%20S100%20Install%20Manual.pdf', 'p.6-11 (flashed standoff / base attachment), p.16-19 (flashed L-foot + flashing/lag into rafter)', '/manufacturer-assets/racking_detail_snapnrack-100.png', 'SnapNrack Series 100 Roof Mount System Code Compliant Installation Manual', TRUE, '40-page genuine SnapNrack Series 100 install manual, text-extracted (cover ''SerieS 100 Roof Mount SySteM Code Compliant Installation Manual, SnapNrack Residential PV Mounting Systems'', 4.94MB). Roof-attachment cross-sections: flashed standoff and flashed L-foot (flashing + lag into rafter). NOTE: manufacturer-native URL snapnrack.com/wp-content/uploads/2019/05/S100-UL-Install-Manual_v2.0_web.pdf now serves the site search HTML instead of the PDF, so this GridAlternatives-hosted copy is the resolving source. Reseller mirrors: solarelectricsupply.com, ressupply.com. Tile-replacement variant manual: https://snapnrack.com/wp-content/uploads/2019/05/Series-100-Tile-Replacement-Install-Manual_v.1.2.pdf'),
  ('racking_detail:quickmount-classic', 'racking_detail', 'quickmount-classic', 'QuickMount PV', 'QM-Classic (Classic Composition Mount, QMSC)', 'image', 'https://files.ironridge.com/quickmount/QMPV-datasheet-QMSC-ClassicComp-web.pdf', 'p.1-2 (full: lag withdrawal spec + pilot-hole-into-rafter install + Elevated Water Seal flashing cross-section)', '/manufacturer-assets/racking_detail_quickmount-classic.png', 'Quick Mount PV Classic Composition Mount (QMSC) - Datasheet & Installation Instructions', TRUE, 'Official Quick Mount PV doc now hosted on files.ironridge.com (IronRidge/Esdec owns Quick Mount PV, so this is effectively first-party). Text-extracted: lag-bolt withdrawal table + note ''thread must be embedded in a rafter'', pilot-hole drilling detail, Elevated Water Seal flashing, (c) 2019 Quick Mount PV, 2.25MB. Datasheet/instruction sheet (cross-section on p.1-2), not a long manual. Manufacturer-native quickmountpv.com fails TLS (expired cert). Fuller successor-product doc: QBase Composition Mount Installation Manual - https://files.ironridge.com/qmpv/resources/brochures/QMPV_QBase_Composition_Mount_Installation_Manual.pdf'),
  ('racking_detail:quickmount-tile', 'racking_detail', 'quickmount-tile', 'QuickMount PV', 'QM-Tile (Tile Replacement Mount, QMTRM)', 'image', 'https://files.ironridge.com/quickmount/QMPV-datasheet-QMTRM-TileReplacement-web.pdf', 'p.2-7 (flashing + lag-into-rafter attachment step and step-by-step watertight detail)', '/manufacturer-assets/racking_detail_quickmount-tile.png', 'Quick Mount PV Tile Replacement Mount (Elevated Water Seal Technology) - Installation Instructions', TRUE, '8-page official Quick Mount PV Tile Replacement Mount install instructions on files.ironridge.com. Text-extracted: p.1 ''Tile Replacement Mount Elevated Water Seal Technology - For use with Flat, S & W shaped tiles'', p.2 flashing + lag-into-rafter attachment, watertight detail p.3-7, 3.97MB. Drops in a metal ''tile'' + subflashing. Flat-tile hook variant alt: QMFTM Specialty Flat Tile Mount - https://s3.amazonaws.com/ecodirect_docs/QuickMount/QMPV-datasheet-QMFTM-SpecFlatTile-web.pdf'),
  ('racking_detail:s5-pvkit', 'racking_detail', 's5-pvkit', 'S-5!', 'PVKit 2.0', 'image', 'https://sunwatts.com/content/manual/S5-PVKIT-2.0-Install-Manual.pdf', 'p.1-4 and p.15-18 (S-5! clamp on standing seam, setscrews that dimple not penetrate seam, stainless PV disc, module frame cross-section), mounting-disc callout ~p.21', '/manufacturer-assets/racking_detail_s5-pvkit.png', 'S-5! PV Kit 2.0 Installation Instructions', TRUE, '24-page genuine S-5! doc, text-extracted (p.1 ''The Right Way to attach almost anything to metal roofs! www.S-5.com / PV Kit 2.0 Installation Instructions / S-5!'', 4.87MB). Standing-seam metal-roof rail-less cross-section: S-5! clamp gripping seam via setscrews (no penetration), PV Disk / mounting disc, direct module frame attach. sunwatts.com is a reseller mirror of the authentic S-5! manual (branding/phone all S-5!). S-5''s own-domain PDF paths 403 / redirect to homepage, live product page: https://www.s-5.com/products/solar-panels-on-metal-roof-pvkit-2-0/ . Other verified mirrors: englertinc.com, lmcurbs.com.'),
  ('racking_detail:k2-crossrail', 'racking_detail', 'k2-crossrail', 'K2 Systems', 'CrossRail', 'image', 'https://k2-systems.com/wp-content/uploads/2022/09/CrossRail-AI-US.pdf', 'p.11-18 (roof attachments: composition ~p.11, tile ~p.11, metal ~p.12, assembly/rail-clamp/attachment detail p.13-18), torque specs p.8, components p.9', '/manufacturer-assets/racking_detail_k2-crossrail.png', 'K2 Systems CrossRail System - Assembly Instructions (US)', TRUE, 'Fetched from official k2-systems.com (3.17MB, ~24-25 pp) and text-extracted, cover ''Connecting Strength CrossRail System ASSEMBLY INSTRUCTIONS''. Roof-attachment cross-section for comp shingle / tile / metal roof plus the rail/clamp assembly detail. Alt mirrors that also resolve: sunwatts.com/content/manual/K2_CrossRail_mounting_installation_manual.pdf. Separate K2 docs exist for Tilt-Up, Ground Mount, and Shared Rail variants if needed.'),
  ('racking_detail:ecofasten-rockit', 'racking_detail', 'ecofasten-rockit', 'EcoFasten', 'Rock-It Gen 4', 'image', 'https://ecofastensolar.com/wp-content/uploads/2023/04/RockIt-InstallationGuide.pdf', 'p.11-15 (snap lines / flashing+lag+gasket+comp-slide attachment, screw placement & driving, deck-mounted, rafter hit/miss), system/flashing components p.5-7', '/manufacturer-assets/racking_detail_ecofasten-rockit.png', 'EcoFasten Complete Rail-Less Racking System Installation Guide (RockIt) v4.3 (rev 11/20/25)', TRUE, 'Fetched from official ecofastensolar.com (Esdec/EcoFasten, 1.83MB, ~34-35 pp) and text-extracted, cover ''COMPLETE RAIL-LESS RACKING SYSTEM INSTALLATION GUIDE, VERSION v4.3, REVISION DATE 11/20/25''. v4.3 IS the current Gen 4 Rock-It doc (supersedes Rock-It 3.0). Lag-screw-through-comp-slide with flashing/gasket into rafter cross-section. Mirror: LA County dpw.lacounty.gov EcoFasten Rock-It Installation Guide.pdf.'),
  ('racking_detail:tesla-panel-mount-comp-rafter', 'racking_detail', 'tesla-panel-mount-comp-rafter', 'Tesla', 'Comp Rafter mount', 'image', 'https://energylibrary.tesla.com/docs/Public/Solar/Retrofit/InstallManual/Panels/en-us.pdf', 'Tesla Panel Mount - Comp Rafter section (Front Skirt / roof-attachment-into-rafter / flashing steps)', '/manufacturer-assets/racking_detail_tesla-panel-mount-comp-rafter.png', 'Tesla Solar Panel Installation Manual (Retrofit) - Tesla Panel Mount, Comp Rafter section', FALSE, 'Genuine Tesla-published path (surfaced in search with correct Tesla titles) but NOT programmatically verifiable: energylibrary.tesla.com is behind Akamai and returns 403 to WebFetch/curl even with a browser user-agent. The consolidated Panels install manual PDF explicitly lists ''Tesla Panel Mount - Comp Rafter'' and ''Tesla Panel Mount - Tile''. Mount-specific section landing page (also genuine, Akamai-gated): https://energylibrary.tesla.com/docs/Public/Solar/Retrofit/InstallManual/CompRafter/en-us/ . Hardware cross-section datasheet: https://energylibrary.tesla.com/docs/Public/Solar/Retrofit/Datasheet/TeslaPanelMount/CatalogTeslaPanelMount.pdf . ACTION: open in a normal browser to capture the Comp Rafter roof-attachment/flashing detail, only server-side fetching is blocked.'),
  ('racking_detail:tesla-panel-mount-tile', 'racking_detail', 'tesla-panel-mount-tile', 'Tesla', 'Tile mount', 'image', 'https://energylibrary.tesla.com/docs/Public/Solar/Retrofit/InstallManual/Panels/en-us.pdf', 'Tesla Panel Mount - Tile section (tile-roof attachment / flashing steps)', '/manufacturer-assets/racking_detail_tesla-panel-mount-tile.png', 'Tesla Solar Panel Installation Manual (Retrofit) - Tesla Panel Mount, Tile section', FALSE, 'Genuine Tesla-published path but NOT programmatically verifiable for the same Akamai 403 reason. Both Tile and Comp Rafter mounts are covered in this consolidated Panels install manual PDF (search snippet explicitly lists ''Tesla Panel Mount - Tile''). Mount-specific section landing page (genuine, Akamai-gated): https://energylibrary.tesla.com/docs/Public/Solar/Retrofit/InstallManual/Tile/en-us/GUID-8D6EEA59-19ED-429B-B074-D6B891AC9AC7.html . Do NOT confuse with the Tesla SOLAR ROOF (glass tile shingle) manual at .../Solar/Roof/InstallManual/ - different product. ACTION: open in a normal browser to capture the tile-roof attachment & flashing detail.'),
  ('racking_detail:unirac-rm10-evo', 'racking_detail', 'unirac-rm10-evo', 'Unirac', 'RM10 EVO (ballasted flat roof)', 'image', 'https://unirac.com/document/rm10-evo-install-guide/view/', 'full (ballast-block configs, roof attachment, RM Flashloc, roof-pad detail drawings)', '/manufacturer-assets/racking_detail_unirac-rm10-evo.png', 'RM10 EVO Code-Compliant Installation Guide', TRUE, 'Official Unirac domain, resolves 200 application/pdf (11.2 MB). NOTE: the older direct CDN path (bsk-pdf-manager/2024/11/RM10EVO_Installation-Guide_20240823.pdf) now 404s, use the technical-library document URL above, which serves the live PDF. RM10 EVO is a 10-degree ballasted TILT flat-roof system (three components: field bay, north-row bay, universal clamp).'),
  ('racking_detail:ironridge-flat-roof', 'racking_detail', 'ironridge-flat-roof', 'IronRidge', 'BX System (ballasted flat roof / tilt)', 'image', 'https://files.ironridge.com/flat-roof-mounting/resources/brochures/IronRidge_BX_System_Installation_Manual.pdf', 'full (BX chassis assembly, 5/10-degree tilt, clamping and attachment details)', '/manufacturer-assets/racking_detail_ironridge-flat-roof.png', 'IronRidge BX System Installation Manual (v4.2)', TRUE, 'Official IronRidge CDN (files.ironridge.com), resolves 200 application/pdf (1.6 MB). BX chassis clamps modules at 5 or 10 degree tilt, landscape orientation, UL 2703. For a rail-based tilt alternative, IronRidge also publishes Tilt Mount and Aire Tilt Mount manuals on the same CDN (Tilt Mount manual verified 200). The equipment_id ''ironridge-flat-roof'' best maps to the BX ballasted system.'),
  ('racking_detail:renusol-console-plus', 'racking_detail', 'renusol-console-plus', 'Renusol', 'Console+ / CS+ (flat-roof ballast tray)', 'pdf', 'https://www.renusol.com/en/instructions-data/', 'full', NULL, 'Renusol CS+ Installation Guide (multi-language) / ConSole+ Ground Fixing Manual', FALSE, 'Renusol instructions-data landing page is the authoritative index (Renusol official domain). The direct CS+ PDF is linked from there (a 2024 all-languages CS+ Installation Guide) but the exact deep-link was not cleanly extractable by the fetch tool (path came back mangled), so left as the index page rather than fabricate a URL. Distributor mirror that DID resolve for the older ConSole ballast manual: https://www.pluginsolar.co.uk/wp-content/uploads/2023/10/Renusol-Console-Installation-Manual.pdf . Renusol also hosts the VS+ install guide at https://www.renusol.com/files/content/Downloads/Installationsanleitungen/VS/20231219_EN_VS+_InstallationGuide.pdf (same download tree). Recommend a follow-up fetch of the instructions-data page to capture the exact CS+ deep link before ingesting.'),
  ('racking_detail:sollega-fc350', 'racking_detail', 'sollega-fc350', 'Sollega', 'FastRack FR510', 'image', 'https://sollega.com/downloads/fr510/Sollega%20installation%20Manual%20Rev%20626.pdf', 'full (mechanical anchor detail, clamping locations, 5/10-deg assembly)', '/manufacturer-assets/racking_detail_sollega-fc350.png', 'Sollega FastRack FR510 Installation Manual (Rev 626)', TRUE, 'NO product named ''FC350'' exists in Sollega''s catalog or downloads (verified sollega.com/downloads). Sollega''s flat-roof racking is the FastRack FR510 (glass-filled nylon injection-molded base, 5 or 10 deg). This FR510 install manual resolves 200 application/pdf (24 MB) on the official sollega.com domain and is the correct structural/attachment detail source. Sollega downloads page also lists a standalone ''FR510 Mechanical Anchor Detail'' and ''FR510-6dg Clamping Locations'' if a single-detail sheet is preferred. equipment_id kept as-is per instructions, model field flags the substitution.'),
  ('racking_detail:unirac-rm10-evo-ground', 'racking_detail', 'unirac-rm10-evo-ground', 'Unirac', 'GFT (Ground Fixed Tilt) ground mount', 'image', 'https://unirac.com/document/ground-fixed-tilt-install-guide/view/', 'full (pile/foundation, cross-section, tilt-table attachment details)', '/manufacturer-assets/racking_detail_unirac-rm10-evo-ground.png', 'Unirac GFT Ground Fixed Tilt Installation Guide', TRUE, 'IMPORTANT: Unirac RM10 EVO is a FLAT-ROOF ballasted product ONLY, Unirac''s actual ground-mount is GFT (Ground Fixed Tilt), UL 2703 bonded module-frame-through-pile. This is the correct ground-mount detail doc. Official Unirac domain, resolves 200 application/pdf (7.4 MB). Older CDN path (bsk-pdf-manager/2025/01/GFT_Installation-Guide_20241129.pdf) now 404s, use the technical-library document URL above which serves the live PDF.'),
  ('racking_detail:schletter-classic', 'racking_detail', 'schletter-classic', 'Schletter', 'Ground mount rail (PvMax / FS System)', 'image', 'https://portal.segensolar.co.za/reseller/docs/Schletter/PlanningAndInstallationManual.pdf', 'full (ground-mount rail cross-sections, foundation/ramming profile, bracing details)', '/manufacturer-assets/racking_detail_schletter-classic.png', 'Schletter Solar Mounting Systems - Mounting & Project Planning Manual (PvMax ground mount)', TRUE, 'Resolves 200 application/pdf (2.9 MB) via a Schletter reseller portal (segensolar), not schletter-group.com directly. Schletter''s own download center is at https://www.schletter-group.com/download-center/type/mounting-instructions/ (index, not a direct PDF). A verified-200 official-Schletter-branded PvMax ground-mount install manual mirror: https://shop.frankensolar.ca/content/documentation/Schletter/Install_Manual_Schletter_PvMax-Installation-Manual_(frankensolar).pdf (200 application/pdf, 1.9 MB). Schletter also publishes an ETL FS-System ground-mount manual. ''Classic'' is not a current Schletter model name, PvMax/FS are the ground-mount lines.'),
  ('racking_detail:terrasmart-glide', 'racking_detail', 'terrasmart-glide', 'TerraSmart', 'GLIDE (ground-screw fixed-tilt)', 'image', 'https://www.terrasmart.com/wp-content/uploads/2021/11/SS32-Ground-Screws.pdf', 'full', '/manufacturer-assets/racking_detail_terrasmart-glide.png', 'TerraSmart Ground Screw Spec Sheet (SS32) / GLIDE Ballast Spec Sheet (SS33)', TRUE, 'TerraSmart''s full TerraGlide Installation Manual (52 pp) is not exposed as a public PDF on terrasmart.com (only hosted on ManualsLib, third-party). The manufacturer DOES publish spec sheets on its own domain that carry the key detail drawings: SS32 Ground Screws (verified 200, 112 KB) and SS33 GLIDE Ballast (verified 200 at https://www.terrasmart.com/wp-content/uploads/2021/12/SS33-GLIDE-Ballast.pdf, 146 KB). Full install manual (third-party, unverified as manufacturer-official): https://www.manualslib.com/manual/3007475/Terrasmart-Terraglide.html . GLIDE variants: GLIDE Agile (ground screw) and GLIDE Wave (ballast).'),
  ('racking_detail:polar-racking-pr-ground', 'racking_detail', 'polar-racking-pr-ground', 'Polar Racking', 'Ground mount (PRG / PRU)', 'image', 'http://polarracking.com/wp-content/uploads/2016/09/PRG-Installation-Manual-Rev-17.pdf', 'full (post/foundation, rail cross-section, module attachment details)', '/manufacturer-assets/racking_detail_polar-racking-pr-ground.png', 'Polar Racking PRG Installation Manual (Rev 17)', TRUE, 'Official polarracking.com domain, resolves 200 application/pdf (5.4 MB). PRG = Polar Racking Ground (commercial ground mount). For utility-scale, the PRU manual also resolves 200 (5.2 MB): http://www.polarracking.com/wp-content/uploads/2015/05/Polar-Racking-PRU-Manual-proof-9.pdf . Current product line is now branded ''CORE'' (overview PDF at polarracking.com/wp-content/uploads/2022/09/), PRG is the appropriate detailed install/structural manual.'),
  ('racking_detail:nextracker-nx-horizon', 'racking_detail', 'nextracker-nx-horizon', 'NEXTracker', 'NX Horizon single-axis tracker', 'pdf', 'https://www.nextracker.com/wp-content/uploads/2019/09/09-11-19_NEXT_SellSheet_NXHorizon.pdf', 'full', NULL, 'NEXTracker NX Horizon Sell Sheet / NX Horizon 2.4.x Installation Manual', FALSE, 'The NX Horizon sell sheet on the official nextracker.com domain exists but returned HTTP 429 (rate-limited) on repeated fetch attempts, not a 404 - URL is real but could not be confirmed-open this session. The full NX Horizon 2.4.x Installation Manual (the doc with slew-drive/BHA/torque-tube/pier cross-section detail drawings needed for permit) is NOT published as a public PDF on nextracker.com, it circulates via Scribd and AHJ/utility filings (e.g. NY DPS Appendix 5-C, and https://www.scribd.com/document/759091630/ Rev C). Manufacturer distributes install manuals to EPCs under login. Recommend sourcing the install manual from a permitted-project filing rather than a fabricated nextracker.com deep link.'),
  ('racking_detail:gamechange-gcx-tracker', 'racking_detail', 'gamechange-gcx-tracker', 'GameChange Solar', 'Genius Tracker (GCX) single-axis tracker', 'image', 'https://www.eastpointenergycenter.com/wp-content/uploads/sites/3/2019/09/Appendix-2-2-Gamechange-Solar-Genius-TrackerTM-Data-Sheet.pdf', 'full (datasheet)', '/manufacturer-assets/racking_detail_gamechange-gcx-tracker.png', 'GameChange Solar Genius Tracker Data Sheet / Genius Tracker 2P Installation Manual', TRUE, 'GameChange Solar does NOT publish a public installation manual PDF on its own domain (gamechangesolar.com redirects to gamechangeenergy.com, only product pages + training, no downloadable manual). The datasheet above resolves 200 application/pdf (390 KB) but is hosted on a project-filing site (eastpointenergycenter), not the manufacturer domain - it is an authentic GameChange ''Genius Tracker'' datasheet embedded in an AHJ appendix. The actual Genius Tracker 2P Installation Manual (with pile/bearing/torque-tube detail drawings) is only found on Scribd (https://www.scribd.com/document/971554187/, Rev 3.0, 2022), unverified as manufacturer-official. ''GCX'' is GameChange''s tracker line, verify exact model designation with the vendor before ingest.'),
  ('racking_detail:soltec-sf7', 'racking_detail', 'soltec-sf7', 'Soltec', 'SF7 (two-in-portrait single-axis tracker)', 'image', 'https://soltec.com/uploads/2024/01/Datasheet-SF7_v12.pdf', 'full (datasheet)', '/manufacturer-assets/racking_detail_soltec-sf7.png', 'Soltec SF7 Datasheet (v12)', TRUE, 'Official soltec.com domain, resolves 200 application/pdf (989 KB). This is the SF7 DATASHEET (dimensions, pier/bearing/drive layout, structural specs) - Soltec does NOT publish a downloadable full install manual publicly, they state their installation guidance is an interactive AR/3D tool for installers, not a PDF. Datasheet is the best manufacturer-official visual/spec source for permit reference. SF7 US variant page: soltec.com/en/solutions/products/sf7-us/.'),
  ('racking_detail:pvhardware-titan', 'racking_detail', 'pvhardware-titan', 'PV Hardware', 'AxoneDuo Single Axis Tracker', 'image', 'https://pvhardware.com/documents/Axone-Duo-Datasheet_email.pdf', 'full (datasheet)', '/manufacturer-assets/racking_detail_pvhardware-titan.png', 'PVH Axone Duo Datasheet / Axone A9 Installation Manual (AXD-PVH-AS-MAN-0001-03)', TRUE, 'CORRECTION: ''Titan'' is NOT a PV Hardware model. ''Titan'' trackers are made by Axial (Axial Titan) and APA Solar (TITAN Series) - different companies. PVH''s single-axis trackers are Axone / AxoneDuo / AxoneDuo Infinity. The Axone Duo datasheet on the official pvhardware.com domain resolves 200 application/pdf (778 KB) and carries the tracker cross-section/drive/torque layout. PVH''s full Axone Installation Manual (AXD-PVH-AS-MAN-0001-03, 7-step assembly with detail drawings) is not on pvhardware.com publicly - only on Scribd (https://www.scribd.com/document/671463280/), unverified as manufacturer-official. RECOMMEND: reconcile the equipment_id/brand - if the intended product really is a ''Titan'' tracker, the correct manufacturer is Axial or APA Solar, not PVH.'),
  ('racking_detail:solfence', 'racking_detail', 'solfence', 'Sol Fence LLC', 'SOL Fence (vertical bifacial solar privacy fence)', 'pdf', 'https://www.solfence.solar/', NULL, NULL, '(no public installation manual / structural detail PDF found)', FALSE, 'HONEST RESULT: Sol Fence LLC (Newburgh, IN, founded 2024) publishes NO public installation manual, datasheet, or structural detail PDF. Their site (solfence.solar, resolves 200) is marketing-only - product pages (residential/commercial), FAQ, and a gated contractor training/distributor program (''step-by-step install support'' and ''online instruction'' are delivered to authorized installers, not as a downloadable PDF). Extensive search found no .pdf on the domain or third-party mirrors. Ray previously has 4 SolFence vendor PDFs from Sol Fence LLC in his files (per memory: solfence-equipment-data.md) - those internal PDFs are the only real structural/spec source, there is no public web asset to scrape. To populate this library entry, use Ray''s existing vendor PDFs, not a web URL.'),
  ('module_spec:rec-alpha-pure-430', 'module_spec', 'rec-alpha-pure-430', 'REC Group', 'Alpha Pure-R 430W', 'image', 'https://www.recgroup.com/sites/default/files/2025-01/Web_DS_REC_Alpha_Pure-R_EN%20US.pdf', 'full', '/manufacturer-assets/module_spec_rec-alpha-pure-430.png', 'REC Alpha Pure-R Datasheet (400-430W, Heterojunction/HJT)', TRUE, 'Official REC Group US datasheet. Single sheet covers the 400-430W Alpha Pure-R series, 430W is the top of range. HTTP 200 application/pdf (1.34 MB) confirmed. Newer IEC/AU-CEC rev also live: https://www.recgroup.com/sites/default/files/2025-11/DS_Alpha_Pure-R_IEC_EN_AUCEC_101125_0.pdf (use the EN-US one for US permits).'),
  ('module_spec:rec-alpha-pure-405', 'module_spec', 'rec-alpha-pure-405', 'REC Group', 'Alpha Pure-R 405W', 'image', 'https://www.recgroup.com/sites/default/files/2025-01/Web_DS_REC_Alpha_Pure-R_EN%20US.pdf', 'full', '/manufacturer-assets/module_spec_rec-alpha-pure-405.png', 'REC Alpha Pure-R Datasheet (400-430W, Heterojunction/HJT)', TRUE, 'SAME official REC US datasheet as the 430W SKU. The Alpha Pure-R series sheet spans 400/405/410/415/420/425/430 Wp in one table, so 405W is on this sheet. HTTP 200 application/pdf confirmed.'),
  ('module_spec:jinko-tiger-neo-580', 'module_spec', 'jinko-tiger-neo-580', 'Jinko Solar', 'Tiger Neo 580W (N-type)', 'image', 'https://jinkosolarcdn.shwebspace.com/uploads/JKM580-605N-72HL4-(V)-F8-EN.pdf', 'full', '/manufacturer-assets/module_spec_jinko-tiger-neo-580.png', 'JinkoSolar Tiger Neo N-type 72HL4-(V) 580-605W Mono-Facial Datasheet', TRUE, 'Official Jinko CDN (jinkosolarcdn.shwebspace.com). Mono-facial N-type TOPCon series JKM580-605N-72HL4-(V), 580W = bottom SKU of this sheet (JKM580N). HTTP 200 application/pdf (275 KB) confirmed. For the bifacial dual-glass variant instead, use https://jinkosolarcdn.shwebspace.com/uploads/JKM560-580N-72HL4-BDV-F4-EN.pdf (560-580W). Chose mono-facial as the standard rooftop module.'),
  ('module_spec:cs-hiku7-600', 'module_spec', 'cs-hiku7-600', 'Canadian Solar', 'HiKu7 600W', 'image', 'https://static.csisolar.com/wp-content/uploads/2020/10/27105931/CS-Datasheet-HiKu7_CS7N-MS_v2.41_EN.pdf', 'full', '/manufacturer-assets/module_spec_cs-hiku7-600.png', 'Canadian Solar HiKu7 CS7N-MS Mono PERC Datasheet (645-675W)', FALSE, 'WATTAGE MISMATCH: the current CSI Solar HiKu7 CS7N-MS US datasheet covers 645-675W, NOT 600W. No official 600W HiKu7 US datasheet found, a 600W HiKu7 would be an older/other-region SKU. URL resolves (HTTP 200 application/pdf, 394 KB) and is the official CSI datasheet, but it does NOT contain a 600W variant. Recommend confirming the exact HiKu7 model/wattage in the equipment DB before embedding, either update the SKU to a 645-675W HiKu7, or source the specific 600W bifacial (CS7N-xxxTB-AG) sheet if that is the real product.'),
  ('module_spec:longi-himo6-580', 'module_spec', 'longi-himo6-580', 'LONGi Solar', 'Hi-MO 6 580W', 'image', 'https://static.longi.com/Hi_MO_6_Explorer_LR_5_72_HTD_550_580_M_V03_UT_aa561c61b7.pdf', 'full', '/manufacturer-assets/module_spec_longi-himo6-580.png', 'LONGi Hi-MO 6 Explorer LR5-72HTD 550-580M Datasheet', TRUE, 'Official LONGi CDN (static.longi.com). Hi-MO 6 Explorer, model LR5-72HTD, 550-580M range, 580W is the top SKU. HTTP 200 application/pdf (1.63 MB) confirmed. This is a 72-cell utility/commercial format Hi-MO 6 (the 580W class). Residential Hi-MO 6 is a smaller 54/60-cell ~410-450W format.'),
  ('module_spec:trina-vertex-s-435', 'module_spec', 'trina-vertex-s-435', 'Trina Solar', 'Vertex S 435W', 'image', 'https://static.trinasolar.com/sites/default/files/Datasheet_Vertex_S_DE09R.08_EN_2022_PA1.pdf', 'full', '/manufacturer-assets/module_spec_trina-vertex-s-435.png', 'Trina Solar Vertex S TSM-DE09R.08 415-435W Datasheet', TRUE, 'Official Trina CDN (static.trinasolar.com). Vertex S TSM-DE09R.08, 415-435W monocrystalline, 435W is top SKU. HTTP 200 application/pdf (3.39 MB) confirmed. Newer N-type dual-glass Vertex S (NEG9RC.27, also to 435W) available at https://static.trinasolar.com/sites/default/files/DT_M_0069_A%20Datasheet_VertexS_NEG9RC.27_EN_2023_A_web.pdf if the product is the newer N-type variant.'),
  ('module_spec:qcells-peak-duo-400', 'module_spec', 'qcells-peak-duo-400', 'Q CELLS', 'Q.PEAK DUO 400W', 'image', 'https://cdn.myced.com/images/Products/ZZ0000/ZZ3048/00000/ZZ304800120_DS.pdf', 'full', '/manufacturer-assets/module_spec_qcells-peak-duo-400.png', 'Qcells Q.PEAK DUO BLK ML-G10+ 385-405W Datasheet', TRUE, 'Q.PEAK DUO BLK ML-G10+ series, 385-405W (Hanwha Qcells America) - 400W is within range. HTTP 200 application/pdf (434 KB). Hosted on a distributor CDN (myced.com) but is the genuine Qcells datasheet. Official Qcells-domain alternative (L-G7.2 385-405 NA): https://us.qcells.com/wp-content/uploads/2023/07/Q_CELLS_Data_sheet_Q.PEAK_DUO_L-G7.2_385-405_2020-07_Rev02_NA.pdf - prefer the us.qcells.com one if you want the manufacturer domain. Match to the exact G-series in the equipment DB (G10+ vs G11).'),
  ('module_spec:silfab-sil430', 'module_spec', 'silfab-sil430', 'Silfab Solar', 'SIL-430 (Prime 430W N-type)', 'image', 'https://silfabsolar.com/wp-content/uploads/2026/05/Silfab-SIL-430-QD-Data-Final.pdf', 'full', '/manufacturer-assets/module_spec_silfab-sil430.png', 'Silfab Prime SIL-430 QD Datasheet (430W, N-type NTC)', TRUE, 'Official silfabsolar.com domain, current SIL-430 QD (Silfab Prime, N-type NTC, 430W, 22.1% eff, 1721x1133x35mm). HTTP 200 application/pdf (3.51 MB) confirmed live from Silfab''s resources page. NOTE: older date-stamped QD URLs (2024/03, 2024/09) now 404 - this 2026/05 file is the current one. If the DB product is the Silfab ELITE 430 BG+ (bifacial, P-type) instead, use https://silfabsolar.com/wp-content/uploads/2023/09/Silfab-SIL-430-BG-Data-Generic-20230906-Final.pdf (also verified 200).'),
  ('module_spec:pan-evervolt-410', 'module_spec', 'pan-evervolt-410', 'Panasonic', 'EverVolt 410W (EVPV410H)', 'image', 'https://es-media-prod.s3.amazonaws.com/media/components/panels/spec-sheets/evervolt_410_400_datasheet.pdf', 'full', '/manufacturer-assets/module_spec_pan-evervolt-410.png', 'Panasonic EverVolt H Series 410W/400W Datasheet', TRUE, 'EverVolt H Series, 410W and 400W (EVPV410H / EVPV400H), 22.2% eff, Panasonic Life Solutions Company of America. HTTP 200 application/pdf (1.19 MB). Hosted on the EnergySage media CDN (es-media-prod.s3) - genuine Panasonic datasheet content. Official Panasonic support page for spec/manual links: https://solar.na.panasonic.com/support/solar-support/solar-catalogs-specs-manuals (files there rotate, the S3 copy is a stable direct PDF).'),
  ('module_spec:sp-maxeon7-440', 'module_spec', 'sp-maxeon7-440', 'SunPower/Maxeon', 'Maxeon 7 440W', 'image', 'https://cdn.prod.website-files.com/6627b4a16340c535bfabf896/668bef1148a5bfbf75c79fbe_Sunpower.pdf', 'full', '/manufacturer-assets/module_spec_sp-maxeon7-440.png', 'SunPower Maxeon 7 SPR-MAX7-XXX-PT Datasheet (435-445W, 40-yr)', TRUE, 'Maxeon 7 SPR-MAX7-XXX-PT residential DC, 435-445W (24.1% eff, 40-yr warranty) - 440W in range. HTTP 200 application/pdf (4.19 MB) confirmed. This is the official Maxeon-published sheet (file sp_max7_112c_PT_435-445_res). NOTE: the sunpower.maxeon.com/int/... copy of this file currently returns HTTP 500, so used the Maxeon-hosted website-files.com CDN copy which resolves. Same document.'),
  ('module_spec:sp-maxeon6-400', 'module_spec', 'sp-maxeon6-400', 'SunPower/Maxeon', 'Maxeon 6 400W', 'image', 'https://maxeon-production.squarespace.com/s/Maxeon-6-DC-410-420-W.pdf', 'full', '/manufacturer-assets/module_spec_sp-maxeon6-400.png', 'Maxeon 6 DC SPR-MAX6-XXX Datasheet (410-420W)', FALSE, 'WATTAGE NOTE: current official Maxeon 6 DC datasheets cover 410-420W and 425-440W, there is NO current 400W Maxeon 6 DC sheet (400W is a discontinued/older SKU). Provided the 410-420W sheet (closest, official Maxeon-hosted squarespace CDN, HTTP 200 application/pdf 715 KB) as the best available. If the DB must show exactly 400W, this sheet does not list 400W - recommend either updating the SKU to 410W or sourcing an archived legacy 400W Maxeon 6 sheet.'),
  ('module_spec:sp-maxeon3-400', 'module_spec', 'sp-maxeon3-400', 'SunPower/Maxeon', 'Maxeon 3 400W', 'image', 'https://maxeon-production.squarespace.com/s/Maxeon-3-DC-Black-405420-W.pdf', 'full', '/manufacturer-assets/module_spec_sp-maxeon3-400.png', 'Maxeon 3 DC Black SPR-MAX3-XXX-BLK-R Datasheet (405-420W)', FALSE, 'WATTAGE NOTE: current official Maxeon 3 DC datasheets are 405-420W (Black) and 415-430W, the 400W Maxeon 3 is a legacy/discontinued SKU no longer on Maxeon''s current sheets. Provided the 405-420W Black sheet (closest, official Maxeon squarespace CDN, HTTP 200 application/pdf 778 KB). Does not list exactly 400W. Recommend updating the SKU to 405W or sourcing the archived legacy SPR-MAX3-400 sheet if 400W is required verbatim.'),
  ('module_spec:tesla-tsp-420', 'module_spec', 'tesla-tsp-420', 'Tesla', 'TSP-420 (Tesla Solar Panel 420W)', 'image', 'https://energylibrary.tesla.com/docs/Public/Solar/Retrofit/Datasheet/TeslaPanelMount/DatasheetTeslaSolarPanel.pdf', 'full', '/manufacturer-assets/module_spec_tesla-tsp-420.png', 'Tesla Solar Panel Datasheet (TSP-415/TSP-420)', TRUE, 'Official Tesla Energy Library. Covers the NEW (2025) Tesla-manufactured Solar Panel line TSP-415 (415W) and TSP-420 (420W), all-black, 18 power zones, 25-yr product warranty. URL resolves via direct GET (HTTP 200 application/pdf, 1.58 MB), WebFetch returns 403 due to Tesla bot-blocking but the document is live and public. NOTE: an older Tesla module sheet (T420S/T425S/T430S) exists separately - this energylibrary sheet is the current TSP-series one.'),
  ('module_spec:tesla-tsp-415', 'module_spec', 'tesla-tsp-415', 'Tesla', 'TSP-415', 'image', 'https://energylibrary.tesla.com/docs/Public/Solar/Retrofit/Datasheet/TeslaPanelMount/DatasheetTeslaSolarPanel.pdf', 'full', '/manufacturer-assets/module_spec_tesla-tsp-415.png', 'Tesla Solar Panel Datasheet (TSP-415/TSP-420)', TRUE, 'SAME official Tesla Energy Library datasheet as TSP-420 - the single sheet lists both TSP-415 (415W) and TSP-420 (420W). HTTP 200 application/pdf (1.58 MB) via direct GET confirmed. WebFetch 403 (bot-block) but the file is public and resolves.'),
  ('module_spec:panel-fence-ps1', 'module_spec', 'panel-fence-ps1', 'Philadelphia Solar', 'PS-M144(HC) 435-455W (Sol Fence module)', 'image', 'https://philadelphia-solar.com/wp-content/uploads/2022/02/PS-M144HC-xxxW435-455W.pdf', 'full', '/manufacturer-assets/module_spec_panel-fence-ps1.png', 'Philadelphia Solar PS-M144(HC)-xxxW Datasheet (435-455W, Half-Cell Mono)', FALSE, 'Official philadelphia-solar.com domain. Half-cell monocrystalline PS-M144(HC), 435-455W. HTTP 200 application/pdf (1.04 MB) confirmed as a real Philadelphia Solar datasheet. verified:false ONLY because the exact Sol-Fence module SKU/wattage is not confirmed from the equipment DB - Philadelphia Solar makes many PS-M series (PS-M60 305-330W, PS-M72 425-450W, PS-M108 400W, PS-M144(HC) 435-455W, PS-M144(HCBF) bifacial 530-555W). Confirm which PS-M model the Sol Fence build actually uses (per memory, Sol Fence LLC uses Philadelphia Solar modules), then pick the matching sheet. Full downloads index: https://philadelphia-solar.com/downloads/'),
  ('inverter_spec:se-7600h', 'inverter_spec', 'se-7600h', 'SolarEdge', 'SE7600H-US', 'pdf', 'https://knowledge-center.solaredge.com/sites/kc/files/se-solaredge-home-hub-inverter-datasheet-nam.pdf', 'full', NULL, 'SolarEdge Home Hub / Energy Hub Inverter — Single Phase with Prism Technology (North America)', TRUE, 'US/North America variant. FAMILY DATASHEET — one PDF covers the SExxxxH-US Energy Hub / Home Hub single-phase line (incl. SE7600H-US, SE10000H-US, SE11400H-US). Reused across se-7600h/se-10000h/se-11400h (and applicable to se-3800h/se-6000h). URL resolved HTTP 200 as a PDF via WebSearch index, direct WebFetch returns 403 (SolarEdge bot-blocks datacenter IPs) but the URL is a real, canonical SolarEdge knowledge-center path. Older-generation HD-Wave alternate datasheet also covers SE3000H-US..SE11400H-US: https://www.solaredge.com/sites/default/files/se-single-phase-us-inverter-datasheet.pdf'),
  ('inverter_spec:se-10000h', 'inverter_spec', 'se-10000h', 'SolarEdge', 'SE10000H-US', 'image', 'https://knowledge-center.solaredge.com/sites/kc/files/se-solaredge-home-hub-inverter-datasheet-nam.pdf', 'full', '/manufacturer-assets/inverter_spec_se-10000h.png', 'SolarEdge Home Hub / Energy Hub Inverter — Single Phase with Prism Technology (North America)', TRUE, 'US variant. Same family datasheet as se-7600h (Energy Hub / Home Hub line). Search index confirms SE10000H-US rated 10000W @ 240V listed on this sheet. WebFetch 403 (bot-block) but canonical SolarEdge KC path, verified via search index.'),
  ('inverter_spec:se-3800h', 'inverter_spec', 'se-3800h', 'SolarEdge', 'SE3800H-US', 'pdf', 'https://www.solaredge.com/sites/default/files/se-single-phase-us-inverter-datasheet.pdf', 'full', NULL, 'SolarEdge Single Phase Inverter with HD-Wave Technology (North America)', TRUE, 'US variant. SE3800H-US is an HD-Wave (non-battery) model — covered by the HD-Wave single-phase family datasheet (model list SE3000H-US / SE3800H-US / SE5000H-US / SE6000H-US / SE7600H-US / SE10000H-US / SE11400H-US per SolarEdge search index). Reused for se-6000h. WebFetch 403 (SolarEdge bot-block) but canonical solaredge.com path, verified via search index.'),
  ('inverter_spec:se-6000h', 'inverter_spec', 'se-6000h', 'SolarEdge', 'SE6000H-US', 'pdf', 'https://www.solaredge.com/sites/default/files/se-single-phase-us-inverter-datasheet.pdf', 'full', NULL, 'SolarEdge Single Phase Inverter with HD-Wave Technology (North America)', TRUE, 'US variant. Same HD-Wave family datasheet as se-3800h, SE6000H-US listed in the model range. WebFetch 403 (bot-block) but canonical path, verified via search index.'),
  ('inverter_spec:se-11400h', 'inverter_spec', 'se-11400h', 'SolarEdge', 'SE11400H-US', 'image', 'https://knowledge-center.solaredge.com/sites/kc/files/se-solaredge-home-hub-inverter-datasheet-nam.pdf', 'full', '/manufacturer-assets/inverter_spec_se-11400h.png', 'SolarEdge Home Hub / Energy Hub Inverter — Single Phase with Prism Technology (North America)', TRUE, 'US variant. Same Energy Hub / Home Hub family datasheet as se-7600h, SE11400H-US (11400W @ 240V) listed. WebFetch 403 (bot-block) but canonical SolarEdge KC path, verified via search index. Also present on the HD-Wave datasheet.'),
  ('inverter_spec:fronius-primo-7-6', 'inverter_spec', 'fronius-primo-7.6', 'Fronius', 'Primo 7.6-1 (208-240)', 'image', 'https://www.fronius.com/en/~/downloads/Solar%20Energy/Datasheets/SE_DS_Fronius_Primo_UL_EN_CA.pdf', 'full', '/manufacturer-assets/inverter_spec_fronius-primo-7-6.png', 'Fronius Primo UL — Datasheet (North America, 208-240V)', TRUE, 'US/North America (UL, 208-240V) variant. FAMILY DATASHEET — one PDF covers the entire Primo UL single-phase line 3.8 / 5.0 / 6.0 / 7.6 / 8.2 / 10.0 / 11.4 / 12.5 / 15.0 kW. Reused across all four fronius-primo ids. URL fetched HTTP 200 (302KB PDF). Alternate US datasheet path also live: https://www.fronius.com/en/~/downloads/Solar%20Energy/Datasheets/SE_DS_Fronius_Primo_EN_US.pdf. Do NOT use the plain EU ''Primo'' sheet (230V) for US permits.'),
  ('inverter_spec:fronius-primo-5-0', 'inverter_spec', 'fronius-primo-5.0', 'Fronius', 'Primo 5.0-1 (208-240)', 'image', 'https://www.fronius.com/en/~/downloads/Solar%20Energy/Datasheets/SE_DS_Fronius_Primo_UL_EN_CA.pdf', 'full', '/manufacturer-assets/inverter_spec_fronius-primo-5-0.png', 'Fronius Primo UL — Datasheet (North America, 208-240V)', TRUE, 'US/North America (UL, 208-240V). Same Primo UL family datasheet as fronius-primo-7.6, covers 5.0-1. PDF fetched HTTP 200.'),
  ('inverter_spec:fronius-primo-8-2', 'inverter_spec', 'fronius-primo-8.2', 'Fronius', 'Primo 8.2-1 (208-240)', 'image', 'https://www.fronius.com/en/~/downloads/Solar%20Energy/Datasheets/SE_DS_Fronius_Primo_UL_EN_CA.pdf', 'full', '/manufacturer-assets/inverter_spec_fronius-primo-8-2.png', 'Fronius Primo UL — Datasheet (North America, 208-240V)', TRUE, 'US/North America (UL, 208-240V). Same Primo UL family datasheet, covers 8.2-1. PDF fetched HTTP 200.'),
  ('inverter_spec:fronius-primo-10-0', 'inverter_spec', 'fronius-primo-10.0', 'Fronius', 'Primo 10.0-1 (208-240)', 'image', 'https://www.fronius.com/en/~/downloads/Solar%20Energy/Datasheets/SE_DS_Fronius_Primo_UL_EN_CA.pdf', 'full', '/manufacturer-assets/inverter_spec_fronius-primo-10-0.png', 'Fronius Primo UL — Datasheet (North America, 208-240V)', TRUE, 'US/North America (UL, 208-240V). Same Primo UL family datasheet, covers 10.0-1 208-240. NOTE: this is the classic Primo UL (SnapINverter), not GEN24. If the GEN24 US variant is required, the separate Primo GEN24 UL datasheet applies (product page: https://www.fronius.com/en-us/usa/solar-energy/installers-partners/technical-data/all-products/inverters/fronius-primo-gen24-ul). Task said ''GEN24 if US'' — classic Primo UL 10.0-1 208-240 is a real US model and is provided here.'),
  ('inverter_spec:sma-sb-7-7', 'inverter_spec', 'sma-sb-7.7', 'SMA', 'Sunny Boy 7.7-US', 'image', 'https://files.sma.de/downloads/SBxx-US-DS-en-41.pdf', 'full', '/manufacturer-assets/inverter_spec_sma-sb-7-7.png', 'SMA Sunny Boy 3.0-US / 3.8-US / 5.0-US / 6.0-US / 7.0-US / 7.7-US — Datasheet', TRUE, 'US variant. FAMILY DATASHEET — one PDF covers the entire Sunny Boy US single-phase line (3.0-US, 3.8-US, 5.0-US, 6.0-US, 7.0-US, 7.7-US). Reused across sma-sb-7.7 / sma-sb-5.0 / sma-sb-6.0. PDF fetched HTTP 200 (657KB, confirmed North America residential datasheet). Official SMA files.sma.de domain.'),
  ('inverter_spec:sma-sb-5-0', 'inverter_spec', 'sma-sb-5.0', 'SMA', 'Sunny Boy 5.0-US', 'image', 'https://files.sma.de/downloads/SBxx-US-DS-en-41.pdf', 'full', '/manufacturer-assets/inverter_spec_sma-sb-5-0.png', 'SMA Sunny Boy 3.0-US / 3.8-US / 5.0-US / 6.0-US / 7.0-US / 7.7-US — Datasheet', TRUE, 'US variant. Same Sunny Boy US family datasheet as sma-sb-7.7, covers 5.0-US. PDF fetched HTTP 200. Official files.sma.de.'),
  ('inverter_spec:sma-sb-6-0', 'inverter_spec', 'sma-sb-6.0', 'SMA', 'Sunny Boy 6.0-US', 'image', 'https://files.sma.de/downloads/SBxx-US-DS-en-41.pdf', 'full', '/manufacturer-assets/inverter_spec_sma-sb-6-0.png', 'SMA Sunny Boy 3.0-US / 3.8-US / 5.0-US / 6.0-US / 7.0-US / 7.7-US — Datasheet', TRUE, 'US variant. Same Sunny Boy US family datasheet, covers 6.0-US. PDF fetched HTTP 200. Official files.sma.de.'),
  ('inverter_spec:sma-sb-10-0', 'inverter_spec', 'sma-sb-10.0', 'SMA', 'Sunny Boy 10.0-US (see note — SB-US line tops at 7.7-US, 10kW = Sunny Tripower Smart Energy)', 'image', 'https://files.sma.de/downloads/STPxx-3SE-40-DS-en-20.pdf', 'full', '/manufacturer-assets/inverter_spec_sma-sb-10-0.png', 'SMA Sunny Tripower 5.0 / 6.0 / 8.0 / 10.0 Smart Energy — Datasheet', TRUE, 'IMPORTANT VARIANT NOTE: There is NO single-phase ''Sunny Boy 10.0-US'' — the residential Sunny Boy US line maxes at 7.7-US. For a 10kW SMA the correct product is the THREE-PHASE Sunny Tripower 10.0 Smart Energy (hybrid, US-available), whose datasheet (STPxx-3SE-40) is provided here and fetched HTTP 200. If a single-phase ~10kW is actually needed, SMA does not offer it in the Sunny Boy US family — flag for equipment-catalog correction.'),
  ('inverter_spec:sungrow-sg5rs', 'inverter_spec', 'sungrow-sg5rs', 'Sungrow', 'SG5.0RS(-US)', 'image', 'https://www.irishellas.com/files/Datasheet_Sungrow_1ph_SG3.0-6.0RS_solar-inverter_AFCI_600Vdc_V11-20210413_ENG.pdf', 'full', '/manufacturer-assets/inverter_spec_sungrow-sg5rs.png', 'Sungrow SG3.0/3.6/4.0/5.0/6.0RS — Single Phase Residential Datasheet', FALSE, 'SG5.0RS covered by the SG3.0-6.0RS single-phase RS-series datasheet. verified:false because this is a Sungrow RS-series datasheet hosted on a distributor (irishellas) mirror and is the INTERNATIONAL RS family (600Vdc, AFCI), NOT a distinct North-America ''-US'' PDF — a separate US ''SG5.0RS-US'' manufacturer datasheet was NOT found on Sungrow''s official domain. ENF directory entry: https://www.enfsolar.com/pv/inverter-datasheet/19510 . Sungrow official product page: https://www.sungrowpower.com/en/products/string-inverter/sg5-0-6-0rs . Recommend Ray confirm the exact US SKU/datasheet from Sungrow NA download center.'),
  ('inverter_spec:sungrow-sg7-6rs', 'inverter_spec', 'sungrow-sg7.6rs', 'Sungrow', 'SG7.6RS(-US)', 'image', 'https://info-support.sungrowpower.com/application/pdf/2022/05/16/DS_20220516_SG5.0_6.0_7.0_8.0_10_12RT_Datasheet_V17_EN.pdf', 'full', '/manufacturer-assets/inverter_spec_sungrow-sg7-6rs.png', 'Sungrow SG5.0/6.0/7.0/8.0/10/12RT — String Inverter Datasheet (nearest published family)', FALSE, 'SG7.6RS is a North America single-phase model, NO distinct official ''SG7.6RS'' or ''SG7.6RS-US'' datasheet PDF was found on Sungrow''s domain via search. The RT-series datasheet (info-support.sungrowpower.com, HTTP-served) is the closest OFFICIAL Sungrow-hosted family sheet but is 3-phase RT, NOT the SG7.6RS single-phase — so ratings will NOT match. verified:false. Recommend pulling the exact SG7.6RS-US datasheet from Sungrow North America (en-us.sungrowpower.com download center) before use in a permit set.'),
  ('inverter_spec:sungrow-sg10rs', 'inverter_spec', 'sungrow-sg10rs', 'Sungrow', 'SG10RS', 'image', 'https://vietnam.sungrowpower.com/upload/file/20220120/DS_SG8.0_9.0_10RS_ENG.pdf', 'full', '/manufacturer-assets/inverter_spec_sungrow-sg10rs.png', 'Sungrow SG8.0/9.0/10RS — Single Phase String Inverter Datasheet', FALSE, 'SG10RS covered by the official Sungrow SG8.0/9.0/10RS single-phase datasheet (hosted on Sungrow''s vietnam regional CDN — genuine Sungrow domain). verified:false only because it is the INTERNATIONAL SG8-10RS family sheet, not a North-America ''-US'' specific PDF, electrical ratings for SG10RS are on it. ENF entry: https://www.enfsolar.com/pv/inverter-datasheet/16914 . Official product page: https://www.sungrowpower.com/en/products/string-inverter/b-sg8-0-9-0-10rs'),
  ('inverter_spec:sungrow-sg15rs', 'inverter_spec', 'sungrow-sg15rs', 'Sungrow', 'SG15RS', 'pdf', NULL, NULL, NULL, 'Sungrow SG15RS — Datasheet (NOT LOCATED on official domain)', FALSE, 'NO datasheet located. No SG15RS PDF surfaced on Sungrow''s official domain or reputable distributor via search. SG15RS may be a newer North-America single-phase model or a mislabeled SKU. Do NOT fabricate — Ray must obtain from Sungrow NA download center (en-us.sungrowpower.com/Downloads) and supply the exact URL.'),
  ('inverter_spec:goodwe-gw5000-ns', 'inverter_spec', 'goodwe-gw5000-ns', 'GoodWe', 'GW5000-NS (NS/DNS single-phase series)', 'image', 'https://en.goodwe.com/Ftp/EN/Downloads/Datasheet/GW_DNS_Datasheet-EN.pdf', 'full', '/manufacturer-assets/inverter_spec_goodwe-gw5000-ns.png', 'GoodWe DNS Series 3-6kW — Single Phase, 2 MPPTs — Datasheet', FALSE, 'GW5000-NS is an older single-phase NS/DNS-series model (5000W). The current official GoodWe DNS-series datasheet (en.goodwe.com, fetched HTTP 200) covers the 3-6kW single-phase D-NS line, GW5000-type ratings appear here but the exact legacy ''GW5000-NS'' SKU may map to GW5000D-NS on the current sheet. verified:false pending exact-SKU confirmation. Legacy NS/DNS user manual: https://nl.goodwe.com/images/download/GW_NS_User%20Manual-EN.pdf . Distributor page for GW5000D-NS: https://www.europe-solarstore.com/goodwe-gw5000d-ns.html'),
  ('inverter_spec:goodwe-gw10k-ms', 'inverter_spec', 'goodwe-gw10k-ms', 'GoodWe', 'GW10K-MS', 'image', 'https://en.goodwe.com/Ftp/EN/Downloads/Datasheet/GW_MS%2016A_Datasheet-EN.pdf', 'full', '/manufacturer-assets/inverter_spec_goodwe-gw10k-ms.png', 'GoodWe MS Series 5-10kW — Single Phase, 3 MPPTs — Datasheet', TRUE, 'FAMILY DATASHEET — official GoodWe MS-series (5-10kW single-phase, 3 MPPT) datasheet covers GW5000-MS ... GW10K-MS. PDF fetched HTTP 200 (935KB) from GoodWe''s official en.goodwe.com domain. Reused for goodwe-gw7700-ms. US G3 variant note: for a strict US-market sheet, GoodWe MS G3(US) documentation exists (GW_MS-US30, covers 5.0-11.4kW G3-US) — MS G3 datasheet: https://en.goodwe.com/Ftp/EN/Downloads/Datasheet/GW_MS%20G3_Datasheet-EN.pdf'),
  ('inverter_spec:goodwe-gw7700-ms', 'inverter_spec', 'goodwe-gw7700-ms', 'GoodWe', 'GW7700-MS', 'image', 'https://en.goodwe.com/Ftp/EN/Downloads/Datasheet/GW_MS%2016A_Datasheet-EN.pdf', 'full', '/manufacturer-assets/inverter_spec_goodwe-gw7700-ms.png', 'GoodWe MS Series 5-10kW — Single Phase, 3 MPPTs — Datasheet', TRUE, 'US variant note: GW7700-MS = 7700W (7680W @ 240V per US G3 manual), part of the MS 5-10kW single-phase family. Same MS-series family datasheet as goodwe-gw10k-ms. PDF fetched HTTP 200. For strict US sheet see MS G3(US): https://en.goodwe.com/Ftp/EN/Downloads/Datasheet/GW_MS%20G3_Datasheet-EN.pdf'),
  ('inverter_spec:tesla-solar-inverter-7p6k', 'inverter_spec', 'tesla-solar-inverter-7p6k', 'Tesla', 'Solar Inverter 7.6kW', 'image', 'https://www.tesla.com/sites/default/files/downloads/tesla_solar_inverter_and_solar_shutdown_device_datasheet.pdf', 'full', '/manufacturer-assets/inverter_spec_tesla-solar-inverter-7p6k.png', 'Tesla Solar Inverter and Solar Shutdown Device — Datasheet', TRUE, 'US variant. FAMILY DATASHEET — one official Tesla PDF covers all Tesla Solar Inverter power classes (3.8 / 5.0 / 5.7 / 7.6 kW, 4 MPPT, 98.0% CEC eff). Reused across tesla-solar-inverter-7p6k and tesla-solar-inverter-3p8k. Canonical tesla.com download path, direct WebFetch returns 403 (Tesla bot-blocks datacenter IPs) but URL is real and confirmed via multiple independent index hits. Mirror on Tesla Energy Library: https://energylibrary.tesla.com/docs/Public/Solar/Inverter/Datasheet/SolarShutdownDevice/en-us/SolarInverter-Datasheet-SolarShutdownDevice.pdf'),
  ('inverter_spec:tesla-solar-inverter-3p8k', 'inverter_spec', 'tesla-solar-inverter-3p8k', 'Tesla', 'Solar Inverter 3.8kW', 'image', 'https://www.tesla.com/sites/default/files/downloads/tesla_solar_inverter_and_solar_shutdown_device_datasheet.pdf', 'full', '/manufacturer-assets/inverter_spec_tesla-solar-inverter-3p8k.png', 'Tesla Solar Inverter and Solar Shutdown Device — Datasheet', TRUE, 'US variant. Same Tesla Solar Inverter family datasheet as tesla-solar-inverter-7p6k, 3.8kW is the entry model in that PDF. Canonical tesla.com path (WebFetch 403 bot-block, real URL). Energy Library mirror: https://energylibrary.tesla.com/docs/Public/Solar/Inverter/Datasheet/SolarShutdownDevice/en-us/SolarInverter-Datasheet-SolarShutdownDevice.pdf'),
  ('microinverter_spec:enphase-iq8plus', 'microinverter_spec', 'enphase-iq8plus', 'Enphase', 'IQ8+ Microinverter (IQ8PLUS-72-2-US)', 'image', 'https://enphase.com/sites/default/files/2021-10/IQ8-Series-DS-US.pdf', 'p.2 spec table, column IQ8PLUS-72-2-US', '/manufacturer-assets/microinverter_spec_enphase-iq8plus.png', 'IQ8 Series Microinverters Data Sheet (North America)', TRUE, 'Combined IQ8 Series NA datasheet (doc IQ8SE-DS-0001-01-EN-US-2022-03-17) covering IQ8, IQ8+, IQ8M, IQ8A, IQ8H in one spec table. IQ8PLUS-72-2-US column: peak output 300 VA, max continuous 290 VA, peak eff 97.6%, CEC 97%, module pairing 235-440W, 240V split-phase. Dims 212x175x30.2 mm. Verified by fetching+reading the PDF. Same family sheet reused for iq8m/iq8h/iq8a ids below.'),
  ('microinverter_spec:enphase-iq8m', 'microinverter_spec', 'enphase-iq8m', 'Enphase', 'IQ8M Microinverter (IQ8M-72-2-US)', 'image', 'https://enphase.com/sites/default/files/2021-10/IQ8-Series-DS-US.pdf', 'p.2 spec table, column IQ8M-72-2-US', '/manufacturer-assets/microinverter_spec_enphase-iq8m.png', 'IQ8 Series Microinverters Data Sheet (North America)', TRUE, 'Same combined IQ8 Series NA family datasheet as iq8plus. IQ8M-72-2-US: peak output 330 VA, max continuous 325 VA, peak eff 97.6%, CEC 97%, module pairing 260-460W. Also documented in the dedicated IQ8M/IQ8A sheet (https://enphase.com/download/iq8m-iq8a-microinverter-data-sheet, doc IQ8MA-12A-DS-0069-03, verified via WebFetch) which lists peak eff 97.8% / CEC 97.5% for the -72-2-US MC4 variant. Using the combined family sheet as primary source.'),
  ('microinverter_spec:enphase-iq8h', 'microinverter_spec', 'enphase-iq8h', 'Enphase', 'IQ8H Microinverter (IQ8H-240-72-2-US)', 'image', 'https://enphase.com/sites/default/files/2021-10/IQ8-Series-DS-US.pdf', 'p.2 spec table, columns IQ8H-240-72-2-US and IQ8H-208-72-2-US', '/manufacturer-assets/microinverter_spec_enphase-iq8h.png', 'IQ8 Series Microinverters Data Sheet (North America)', TRUE, 'Same combined IQ8 Series NA family datasheet. IQ8H-240-72-2-US: peak output 384 VA, max continuous 380 VA, peak eff 97.6%, CEC 97%, module pairing 320-540+W. 208V variant = 366 VA (grid-tied only). Verified by reading the PDF.'),
  ('microinverter_spec:enphase-iq8a', 'microinverter_spec', 'enphase-iq8a', 'Enphase', 'IQ8A Microinverter (IQ8A-72-2-US)', 'image', 'https://enphase.com/sites/default/files/2021-10/IQ8-Series-DS-US.pdf', 'p.2 spec table, column IQ8A-72-2-US', '/manufacturer-assets/microinverter_spec_enphase-iq8a.png', 'IQ8 Series Microinverters Data Sheet (North America)', TRUE, 'Same combined IQ8 Series NA family datasheet. IQ8A-72-2-US: peak output 366 VA, max continuous 349 VA, peak eff 97.6%, CEC 97.5%, module pairing 295-500W. Also on the dedicated IQ8M/IQ8A sheet (IQ8MA-12A-DS-0069-03) which lists 97.7% peak / 97% CEC for the MC4 variant. Using combined family sheet as primary.'),
  ('microinverter_spec:enphase-iq8ac', 'microinverter_spec', 'enphase-iq8ac', 'Enphase', 'IQ8AC Microinverter (IQ8AC-72-M-US)', 'image', 'https://enphase.com/download/iq8ac-microinverter-data-sheet', 'full (dedicated single-model datasheet, doc DSH-00046-5.0-EN-2024-12-10)', '/manufacturer-assets/microinverter_spec_enphase-iq8ac.png', 'IQ8AC Microinverter - North America Data Sheet', TRUE, 'IQ8AC is NOT in the older combined IQ8-Series-DS-US.pdf, it has its own dedicated NA datasheet. IQ8AC-72-M-US @240VAC: peak output 366 VA, max continuous 349 VA, peak eff 97.3%, CEC 97.0%, module pairing 295-500W, dims 212x175x30.2 mm, weight 1.1 kg. Verified by fetching+reading the PDF (marked NORTH AMERICA DATA SHEET). URL is the Enphase /download page which serves the PDF (WebFetch retrieved the binary successfully), note plain curl gets a 403 Cloudflare bot-block but a browser/WebFetch resolves it.'),
  ('optimizer_spec:solaredge-p370', 'optimizer_spec', 'solaredge-p370', 'SolarEdge', 'P370 Power Optimizer', 'pdf', 'https://knowledge-center.solaredge.com/sites/kc/files/se-p-series-add-on-power-optimizer-datasheet.pdf', 'p.2 spec table, column P370', NULL, 'SolarEdge Power Optimizer P370/P401/P404/P485/P500/P505/P601 Data Sheet', TRUE, 'P-Series add-on optimizer family datasheet (doc DS-000047-ENG, dated July 13 2023). P370 column: Rated Input DC Power 370W, Voc max 60V, MPPT 8-60V, Isc 11A, max efficiency 99.5%, weighted 98.8%, dims 129x153x27.5 mm, weight 655g. Verified by downloading+reading the PDF (curl 200 application/pdf, WebFetch itself was 403 due to Radware bot-protection, but the URL resolves fine in a real client). Same family sheet reused for P401.'),
  ('optimizer_spec:solaredge-p401', 'optimizer_spec', 'solaredge-p401', 'SolarEdge', 'P401 Power Optimizer', 'pdf', 'https://knowledge-center.solaredge.com/sites/kc/files/se-p-series-add-on-power-optimizer-datasheet.pdf', 'p.2 spec table, column P401', NULL, 'SolarEdge Power Optimizer P370/P401/P404/P485/P500/P505/P601 Data Sheet', TRUE, 'Same P-Series family datasheet as P370 (DS-000047-ENG). P401 column: Rated Input DC Power 420W (note: model name P401 but rated 420W), Voc max 60V, MPPT 8-60V, Isc 12.5A, max efficiency 99.5%, weighted 98.8%, dims 129x153x29.5 mm, weight 775g. Verified by reading the PDF.'),
  ('optimizer_spec:solaredge-s440', 'optimizer_spec', 'solaredge-s440', 'SolarEdge', 'S440 Power Optimizer (S-Series)', 'pdf', 'https://knowledge-center.solaredge.com/sites/kc/files/se-power-optimizer-s-series-datasheet-na.pdf', 'p.2 spec table, column S440', NULL, 'SolarEdge Residential Power Optimizer for North America S440/S500B/S650B Data Sheet', TRUE, 'S-Series residential NA optimizer family datasheet (doc DS-000018-NA). S440 column: Rated Input DC Power 440W (490W for installs after Sep 1 2025), Voc max 60V, MPPT 8-60V, max continuous input 14.5A (15A post-2025), max efficiency 99.5%, weighted 98.6%, dims 129x155x30 mm, weight 720g, IP68/NEMA6P. Verified by downloading+reading the PDF (curl 200 application/pdf, WebFetch 403 Radware). Family sheet also covers S500B/S650B.'),
  ('optimizer_spec:tigo-ts4-a-o', 'optimizer_spec', 'tigo-ts4-a-o', 'Tigo', 'TS4-A-O Optimizer', 'pdf', 'https://www.tigoenergy.com/documents/datasheet-ts4-a-o-optimization-700w-15a', 'full (direct PDF: https://cdn.prod.website-files.com/5fad551d7419c7a0e9e4aba4/6570a210b20fedb13c961e2b_002-00143-00%201.4%20TS4-A-O%20datasheet%2020231129%20EN.pdf)', NULL, 'Tigo TS4-A-O (Optimization) Data Sheet - EN v1.4', TRUE, 'TS4-A-O module-level optimization/monitoring/rapid-shutdown MLPE (doc 002-00143-00 Rev 1.4). Max output power 700W, max current 15A (Imp)/20A (Isc), input VMP 16-80V, max efficiency 99.6%, dims 139.7x138.4x22.9 mm, weight 520g, IP68/NEMA 3R, MC4/EVO2 connectors, 25yr warranty. Verified by fetching+reading the direct PDF. source_url is the official Tigo landing page, the direct .pdf is on Tigo''s Webflow CDN (cdn.prod.website-files.com), also verified 200 application/pdf.'),
  ('optimizer_spec:tigo-ts4-a-2o', 'optimizer_spec', 'tigo-ts4-a-2o', 'Tigo', 'TS4-A-2O (dual-module optimizer)', 'pdf', 'https://www.tigoenergy.com/documents/datasheet-ts4-a-2f-fire-safety-for-2-modules', 'full (direct PDF: https://cdn.prod.website-files.com/5fad551d7419c7a0e9e4aba4/69d7e7bd08dece46389c4cd5_002-00092-00%202.9%20Datasheet%20TS4-A-2F%2020260320%20-%20EN.pdf)', NULL, 'Tigo TS4-A-2F (Fire Safety for 2 modules) Data Sheet - EN v2.9', FALSE, 'Re-keyed to real product TS4-A-2O dual-module optimizer (equipment-db id tigo-ts4-a-2o). Earlier worker mismatched to TS4-A-2F fire-safety part. Source is the Tigo TS4-A product/datasheet family page. NAMING MISMATCH: Tigo has NO product called ''TS4-A-2''. The TS4-A lineup is TS4-A-O (optimization), TS4-A-S (safety+monitoring), TS4-A-M (monitoring), TS4-A-F (fire safety, 1 module), TS4-A-2F (fire safety, 2 modules). Best match for the ''-2'' id is TS4-A-2F (one unit covering 2 modules). Landing page + direct Webflow-CDN PDF both verified (curl 200 application/pdf, 3.0MB, WebFetch confirmed page title ''Datasheet: TS4-A-2F (Fire Safety for 2 modules) v2.9''). NOTE: TS4-A-2F is a rapid-shutdown/fire-safety MLPE, NOT a power optimizer - if the intended product was truly an optimizer, the correct Tigo optimizer is TS4-A-O (tigo-ts4-a-o above), confirm intent with Ray before wiring.'),
  ('battery_spec:tesla-powerwall-3', 'battery_spec', 'tesla-powerwall-3', 'Tesla', 'Powerwall 3', 'image', 'https://energylibrary.tesla.com/docs/Public/EnergyStorage/Powerwall/3/Datasheet/en-us/Powerwall-3-Datasheet.pdf', 'full', '/manufacturer-assets/battery_spec_tesla-powerwall-3.png', 'Powerwall 3 Datasheet (en-US)', TRUE, 'Official Tesla Energy Library US datasheet. Confirmed content: 13.5 kWh usable, up to 11.5 kW AC continuous per unit, supports up to 20 kW DC solar, integrated solar+battery (hybrid) system, Li-ion NMC. Certs incl. UL 1741, UL 9540, UL 9540A, UL 3741. HTTP 200 application/pdf (1.6 MB) via curl, text extracted and confirmed. WebFetch UA is 403-blocked but the PDF resolves.'),
  ('battery_spec:tesla-powerwall-2', 'battery_spec', 'tesla-powerwall-2', 'Tesla', 'Powerwall 2', 'image', 'https://energylibrary.tesla.com/docs/Public/EnergyStorage/Powerwall/2/Datasheet/en-us/Powerwall-2-Datasheet.pdf', 'full', '/manufacturer-assets/battery_spec_tesla-powerwall-2.png', 'Tesla Powerwall 2 Datasheet (en-US)', TRUE, 'Official Tesla Energy Library US datasheet. Confirmed: fully-integrated AC battery, lithium-ion, 13.5 kWh usable (14 kWh total), 5 kW continuous / 7 kW peak, 120/240 V split phase. Model numbers 1092170/2012170/3012170-xx-y. HTTP 200 application/pdf (290 KB) via curl, text extracted and confirmed. Distinct doc from Powerwall 3.'),
  ('battery_spec:enphase-iq-battery-5p', 'battery_spec', 'enphase-iq-battery-5p', 'Enphase', 'IQ Battery 5P', 'image', 'https://s3.amazonaws.com/ecodirect_docs/ENPHASE/IQ-Battery-5P/Enphase-IQ+Battery-5P-DSH-00010-1_0-EN-US-2023-05-16-Datasheet.pdf', 'full', '/manufacturer-assets/battery_spec_enphase-iq-battery-5p.png', 'Enphase IQ Battery 5P Data Sheet (EN-US)', TRUE, 'US-region datasheet (doc id IQB-5P-DSH-00010-1.0-EN-US). Confirmed: 5.0 kWh total usable, six embedded grid-forming IQ8D-BAT microinverters, 3.84 kVA continuous, LFP, AC-coupled. Official Enphase landing page: https://enphase.com/download/iq-battery-5p-data-sheet (redirects/region-gated). This S3 mirror is the identical US PDF and resolves HTTP 200, text extracted and confirmed.'),
  ('battery_spec:enphase-iq-battery-10t', 'battery_spec', 'enphase-iq-battery-10t', 'Enphase', 'IQ Battery 10T', 'image', 'https://enphase.com/sites/default/files/2021-10/IQ-Battery-10T-DS-EN-US-10-19-2021.pdf', 'full', '/manufacturer-assets/battery_spec_enphase-iq-battery-10t.png', 'Enphase IQ Battery 10T Data Sheet (EN-US)', TRUE, 'Official enphase.com US datasheet. Confirmed: comprises three IQ Battery 3T units, 10.08 kWh total usable, twelve embedded grid-forming microinverters, 3.84 kW, LFP, AC-coupled. HTTP 200 application/pdf, text extracted and confirmed.'),
  ('battery_spec:enphase-iq-battery-3t', 'battery_spec', 'enphase-iq-battery-3t', 'Enphase', 'IQ Battery 3T', 'image', 'https://enphase.com/sites/default/files/2021-10/IQ-Battery-3T-DS-EN-US-10-25-2021.pdf', 'full', '/manufacturer-assets/battery_spec_enphase-iq-battery-3t.png', 'Enphase IQ Battery 3T Data Sheet (EN-US)', TRUE, 'Official enphase.com US datasheet. Confirmed: 3.36 kWh total usable, four embedded grid-forming microinverters, 1.28 kW, LFP, AC-coupled. HTTP 200 application/pdf, text extracted and confirmed.'),
  ('battery_spec:generac-pwrcell-9', 'battery_spec', 'generac-pwrcell-9', 'Generac', 'PWRcell (9 kWh config)', 'image', 'https://s3.amazonaws.com/ecodirect_docs/Generac/Generac-PWRcell-outdoor-batterycabinet-datasheet.pdf', 'full', '/manufacturer-assets/battery_spec_generac-pwrcell-9.png', 'Generac PWRcell Outdoor Rated Battery Cabinet + 3.0 kWh DCB Battery Module Datasheet', TRUE, '9 kWh config = 3x 3.0 kWh DCB modules (M3) in one PWRcell battery cabinet (SKU APKE00028). SINGLE datasheet covers ALL cabinet configs 9-18 kWh (3-6 modules) and up to 36 kWh with a 2nd cabinet. Module model BJ-DCB05ZKBG (G0080040). Generac''s own domain (generac.com) gates every PDF behind a JS/HTML wall (all direct-file URLs return text/html, unfetchable). This ecodirect S3 mirror is the identical Generac datasheet and resolves HTTP 200 application/pdf, text extracted and confirmed. Official page: https://www.generac.com/dealers-installers/solar-battery-installer-support/manuals-spec-sheets/'),
  ('battery_spec:generac-pwrcell-17', 'battery_spec', 'generac-pwrcell-17', 'Generac', 'PWRcell (17 kWh config)', 'image', 'https://s3.amazonaws.com/ecodirect_docs/Generac/Generac-PWRcell-outdoor-batterycabinet-datasheet.pdf', 'full', '/manufacturer-assets/battery_spec_generac-pwrcell-17.png', 'Generac PWRcell Outdoor Rated Battery Cabinet + 3.0 kWh DCB Battery Module Datasheet', TRUE, '17-18 kWh config = 6x 3.0 kWh DCB modules (M6, full cabinet) in one PWRcell battery cabinet (SKU APKE00028). SAME datasheet as generac-pwrcell-9 — Generac PWRcell cabinet spec sheet covers the full 9/12/15/18 kWh module range on one sheet (nominal usable ~17.1 kWh at 6 modules is commonly marketed as the 17 kWh config). Generac.com PDFs are JS/HTML-gated, ecodirect S3 mirror resolves HTTP 200 application/pdf and content confirmed. Official page: https://www.generac.com/dealers-installers/solar-battery-installer-support/manuals-spec-sheets/'),
  ('battery_spec:franklin-apower-15', 'battery_spec', 'franklin-apower-15', 'FranklinWH', 'aPower 2 (15 kWh)', 'image', 'https://sunwatts.com/content/specs/Franklin_battery_aPower_Datasheet.pdf', 'full', '/manufacturer-assets/battery_spec_franklin-apower-15.png', 'FranklinWH aPower Datasheet', TRUE, 'aPower V1.3 ISNA (US) datasheet. Confirmed: 13.6 kWh per unit (expandable to 204 kWh / 15 units per aGate), LFP chemistry, AC-coupled, built-in inverter, 5 kW continuous / 10 kW (10s) peak, 208 V multi-family compliant. NOTE the equipment_id says ''15'' but the product is the 13.6 kWh aPower (single-unit capacity), which the datasheet confirms. Official landing page: https://www.franklinwh.com/document/apower-datasheet (dynamic download page). This sunwatts mirror is the identical FranklinWH aPower V1.3 PDF, resolves HTTP 200 application/pdf, text extracted and confirmed.'),
  ('battery_spec:solaredge-home-battery-10', 'battery_spec', 'solaredge-home-battery-10', 'SolarEdge', 'Home Battery 400V / 10 kWh', 'pdf', 'https://knowledge-center.solaredge.com/sites/kc/files/se-solaredge-home-battery-datasheet-nam.pdf', 'full', NULL, 'SolarEdge Home Battery 400V Datasheet (North America, BAT-10K1P)', TRUE, 'Official SolarEdge knowledge-center North America datasheet. Confirmed: SolarEdge Home Battery 400V, model BAT-10K1P, ~9.7-10 kWh usable, 5 kW continuous / 7.5 kW peak (10s), DC-coupled, optimized for SolarEdge Home Hub inverters, >94.5% roundtrip. HTTP 200 application/pdf, text extracted and confirmed. (WebFetch UA was 403-blocked, curl with browser UA resolves.) US Domestic-Content variant also exists: https://knowledge-center.solaredge.com/sites/kc/files/se-solaredge-home-battery-400V-made-in-the-usa-datasheet-nam.pdf'),
  ('battery_spec:sonnen-eco-10', 'battery_spec', 'sonnen-eco-10', 'sonnen', 'sonnenCore / ecoLinx 10', 'image', 'https://media.sonnengroup.com/410f549b-cb97-4bd2-9959-65a54be0f2a7-en-download', 'full', '/manufacturer-assets/battery_spec_sonnen-eco-10.png', 'sonnenCore+ Technical Specifications (SCORE-P10 / SCORE-P20)', TRUE, 'Official sonnen media server US technical spec sheet for sonnenCore+ (model SCORE-P10 = 10 kWh, SCORE-P20 = 20 kWh). Confirmed: ~10 kWh usable, 4.8 kW nominal, LFP, indoor, UL 9540 listed, stackable to 60 kWh. NOTE: current-generation product is sonnenCore+ (SCORE-P10), the direct successor to the sonnenCore 10 kWh, this is the correct 10 kWh sonnen residential battery datasheet. HTTP 200 application/pdf, text extracted and confirmed. (ecoLinx is a separate discontinued/older sonnen line — not this doc.)'),
  ('battery_spec:tigo-ei-battery-10', 'battery_spec', 'tigo-ei-battery-10', 'Tigo', 'EI Battery', 'image', 'https://assets-global.website-files.com/5fad551d7419c7a0e9e4aba4/614bf48ee6034e58377482eb_Tigo%20Energy_EI%20Battery%20datasheet_EN_09222021.pdf', 'full', '/manufacturer-assets/battery_spec_tigo-ei-battery-10.png', 'Tigo EI Battery Datasheet (TSB-10/20-US)', TRUE, 'Tigo''s own hosted (Webflow assets, tigoenergy.com CDN) EI Battery datasheet. Confirmed: model TSB-10/20-US, PN 002-00084-00, LFP chemistry, ~9.9 kWh per enclosure (9.0 kWh usable), combinable up to 4 batteries (39.6 kWh), 132-month warranty, IP56/NEMA 4. HTTP 200 application/pdf, text extracted and confirmed. This is the BATTERY sheet (a separate EI Inverter datasheet exists at solar-electric.com, not used here).'),
  ('battery_spec:ecoflow-battery-5kwh', 'battery_spec', 'ecoflow-battery-5kwh', 'EcoFlow', 'PowerOcean / Power Kit battery', 'image', 'https://enterprise-service-us-cdn.ecoflow.com/enterprise/documentation/1763710879602/EcoFlow%20PowerOcean%20Battery_Datasheet_EN(1).pdf', 'full', '/manufacturer-assets/battery_spec_ecoflow-battery-5kwh.png', 'EcoFlow PowerOcean LFP Battery Datasheet', TRUE, 'Official EcoFlow enterprise US CDN datasheet for the PowerOcean LFP battery (module SKUs EF BD-5.1-S1 = 5.1 kWh, BD-10.2-S1 = 10.2 kWh, BD-15.3-S1 = 15.3 kWh). 5 kWh config = single BD-5.1-S1 module. LFP chemistry, modular/stackable, >6000 cycles. HTTP 200 application/pdf (1.4 MB), text extracted and confirmed. NOTE: this datasheet describes the 3-phase PowerOcean system (''Made in China''), it is EcoFlow''s official spec doc and the closest match to the requested ~5 kWh EcoFlow PowerOcean battery module.')
