-- 104_seed_manufacturer_assets.sql
-- Seed the manufacturer_assets library with web-sourced manufacturer detail/spec sheets.
-- Auto-generated from worker JSON manifests. Idempotent (ON CONFLICT DO UPDATE).
-- No inline semicolons or double-dashes inside values (migration-runner safe).

ON CONFLICT (id) DO UPDATE SET
  source_url = EXCLUDED.source_url,
  page_ref   = EXCLUDED.page_ref,
  image_url  = EXCLUDED.image_url,
  doc_title  = EXCLUDED.doc_title,
  verified   = EXCLUDED.verified,
  notes      = EXCLUDED.notes;
